import {observe} from '../../dist/fog.js';
const site=(type,x,lane)=>({type,x,lane}),mines=[site('mint',270,0),site('mint',270,2)];
const freeze=v=>{if(v&&typeof v==='object'){Object.values(v).forEach(freeze);Object.freeze(v);}return v;};
export const POLICY_DEFINITIONS=freeze({
 northground:{intent:'North-road warrior screen, ranged support and two siege producers; hold other roads with inherited troops.',plan:[site('barracks',1250,0),site('foundry',1110,0),site('archery',970,0),site('sanctum',690,0),...mines,site('foundry',550,0),site('archery',1110,2),site('barracks',1250,2)]},
 southground:{intent:'Southern infantry and wizard pressure, then screened siege; reinforce center and northern inherited defense.',plan:[site('barracks',1250,2),site('sanctum',1110,2),site('archery',970,2),site('foundry',690,2),site('barracks',550,2),...mines,site('archery',1250,1),site('archery',1110,0)],upgradeOrder:['sanctum','archery','foundry','barracks','mint']},
 middlebreach:{intent:'A direct ground breach through the central archers, using infantry, siege and splash.',plan:[site('barracks',1250,1),site('foundry',1110,1),site('archery',970,1),site('sanctum',550,1),...mines,site('foundry',270,1),site('archery',1250,0),site('archery',1250,2)]},
 supportedRootwarden:{intent:'Durable southern Rootwarden screen backed by archers, siege and wizard damage.',plan:[site('wardenLodge',1250,2),site('archery',1110,2),site('foundry',970,2),site('sanctum',690,2),...mines,site('archery',550,2),site('wardenLodge',1250,0),site('archery',1110,0)],upgradeOrder:['archery','sanctum','wardenLodge','foundry','barracks','mint']},
 supportedair:{intent:'Costly northern automatic flyers supported by ground screens, archers, siege and economy.',plan:[site('aerie',1250,0),site('archery',1110,0),site('barracks',970,0),site('aerie',690,0),site('foundry',550,0),...mines,site('sanctum',410,0),site('archery',1110,2)],upgradeOrder:['archery','aerie','foundry','barracks','sanctum','mint']},
 unsupportedair:{intent:'Buy only aeries beyond the inherited starting camp, concentrating on the center before outer air.',plan:[site('aerie',1250,1),site('aerie',1110,1),site('aerie',970,1),site('aerie',550,1),site('aerie',1250,0),site('aerie',1110,0),site('aerie',1250,2),site('aerie',1110,2)],upgradeOrder:['aerie'],volley:false},
 broadnovice:{intent:'Spread ordinary infantry and archers across three roads, buy mines and broadly upgrade, without a focused siege rush.',plan:[site('barracks',1250,0),site('archery',1250,1),site('barracks',1250,2),site('archery',1110,0),site('archery',1110,2),...mines,site('barracks',970,1),site('archery',550,0),site('archery',550,2)],upgradeOrder:['barracks','archery','mint']},
 safeeconomy:{intent:'Buy both extra mines first, add forward towers, then build a screened northern siege force.',plan:[...mines,site('watchtower',1250,0),site('watchtower',1250,2),site('watchtower',1250,1),site('foundry',1110,0),site('barracks',970,0),site('archery',690,0),site('sanctum',550,0)],citadel:'arrows',upgradeOrder:['mint','foundry','archery','barracks','sanctum','watchtower']},
 idle:{intent:'No paid player actions; observe ordinary adaptive opposition.',plan:[]}
});
export const POLICY_IDS=Object.freeze(Object.keys(POLICY_DEFINITIONS));
export function describePolicy(id){if(!POLICY_DEFINITIONS[id])throw Error('Unknown policy: '+id);return structuredClone({id,...POLICY_DEFINITIONS[id],information:'Fully visible player observation only; no direct state writes. One successful paid action per five seconds including spell and citadel purchases. Plans use fixed sites; failed attempts do not consume cadence.',volley:'Unless disabled, at least five visible enemies within spell radius at x<850, gold>150 and cooldown ready.'});}
export function createPolicy(id){const d=POLICY_DEFINITIONS[id];if(!d)throw Error('Unknown policy: '+id);let next=0,actions=0;return {report:()=>({id,actions,next}),step(g){const s=observe(g,0).state;if(id==='idle'||s.time+1e-7<next||s.winner!==null)return;const commit=r=>{if(r.ok){actions++;next=s.time+5;}return r;};
if(d.volley!==false&&s.gold[0]>150&&s.spellCooldown[0]<=0){const threats=s.units.filter(u=>u.side===1&&u.x<850),target=threats.find(u=>threats.filter(v=>Math.hypot(u.x-v.x,u.y-v.y)<g.ruleset.spell.radius).length>=5);if(target&&commit(g.cast(target.x,target.y,0)).ok)return;}
const own=s.buildings.filter(b=>b.side===0&&b.hp>0);for(const p of d.plan){if(own.some(b=>Math.hypot(b.x-p.x,b.y-g.map.lanes[p.lane])<108))continue;commit(g.build(p.type,p.x,g.map.lanes[p.lane],0));return;}
if(d.citadel&&!s.citadelOptions.sides[0].choice&&commit(g.buyCitadelOption(d.citadel,0)).ok)return;
const order=d.upgradeOrder??['foundry','archery','barracks','sanctum','wardenLodge','aerie','mint'],up=own.filter(b=>b.level<3&&order.includes(b.type)).sort((a,b)=>a.level-b.level||order.indexOf(a.type)-order.indexOf(b.type)||b.x-a.x||a.lane-b.lane);if(up[0])commit(g.upgrade(up[0].id,0));}};}
